        total = sum(amt_map.get(r['po_number'], 0) for r in rows)
        no_event = sum(1 for r in rows if not r.get('last_event_kind'))
        out.append({'title': '逾期未完成采购单', 'detail': '截至2026年9月共有%d笔采购单预计到货日已过期（均为2026-08-20），合计金额%.2f，其中%d笔无任何后续事件记录，状态全部停留在awaiting_payment。' % (len(rows), total, no_event), 'evidence': {'overdue_count': len(rows), 'overdue_amount': round(total, 2), 'no_event_count': no_event}})
    ev = pick(['po_number', 'snapshot_is_null', 'rule_count'])
    if ev:
        rows = ev['rows']
        nulls = sum(1 for r in rows if r.get('snapshot_is_null'))
        out.append({'title': '采购单规则评估缺失', 'detail': '2026年9月提交的%d笔采购单中，%d笔的规则评估快照为空（evaluation_id与rule_count均为null），提交时是否触发规则无法追溯。' % (len(rows), nulls), 'evidence': {'submitted_count': len(rows), 'null_snapshot_count': nulls}})
    ct = pick(['contract_count'])
    if ct and ct['rows'] and ct['rows'][0].get('contract_count') == 0:
        out.append({'title': '合同目标缺失', 'detail': '当前无生效合同记录，年度销售目标与完成度无法计算，9月已确认销售额2231.20缺少考核基准。', 'evidence': {'contract_count': 0}})
    stock = pick(['sku', 'product_name_en', 'stock_on_hand'])
    sold = pick(['sku', 'units_sold'])
    if stock and sold:
        sold_map = {r['sku']: r['units_sold'] for r in sold['rows']}
        for r in stock['rows']:
            s = sold_map.get(r['sku'])
            if s and s > 0:
                days = r['stock_on_hand'] / (s / 30.0)
                out.append({'title': '库存可售天数：%s（%s）' % (r['product_name_en'], r['sku']), 'detail': '期末库存%.0f，9月销量%.0f，按当月日均销量估算仅可售约%.1f天，存在断货风险。' % (r['stock_on_hand'], s, days), 'evidence': {'stock_on_hand': r['stock_on_hand'], 'units_sold': s, 'days_cover': round(days, 1)}})
    return out
